Method.Source:
void modifyForm()
{
    next modifyForm();

    // Security policy for Warehouse
    if (METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
    {
        container siteAndWarehouseCon = METUserSecurityWarehouseList::findSingleSiteAndWarehouseByUser();

        if (conLen(siteAndWarehouseCon) > 0)
        {
            // Set Site field and lock it
            SalesTable.InventSiteId = conPeek(siteAndWarehouseCon, 1);
            SalesTable_ds.object(fieldNum(SalesTable, InventSiteId)).modified();
            SalesTable_ds.object(fieldNum(SalesTable, InventSiteId)).allowEdit(false);

            // Set Warehouse field and lock it
            SalesTable.InventLocationId = conPeek(siteAndWarehouseCon, 2);
            SalesTable_ds.object(fieldNum(SalesTable, InventLocationId)).modified();
            SalesTable_ds.object(fieldNum(SalesTable, InventLocationId)).allowEdit(false);
        }
    }
}
